package com.hospital.smartqueue.doctor.scheduling.application;
import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.doctor.scheduling.api.ScheduleRequest; import com.hospital.smartqueue.doctor.scheduling.domain.*; import com.hospital.smartqueue.doctor.scheduling.infrastructure.*; import com.hospital.smartqueue.doctor.infrastructure.DoctorRepository; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DoctorScheduleService { private final SchedulingAccessContext access; private final DoctorRepository doctors; private final DoctorScheduleRevisionRepository schedules; private final AuditService audit; public DoctorScheduleService(SchedulingAccessContext a,DoctorRepository d,DoctorScheduleRevisionRepository s,AuditService audit){access=a;doctors=d;schedules=s;this.audit=audit;}
 @Transactional public DoctorScheduleRevision save(UUID hospitalId,UUID branchId,UUID doctorId,ScheduleRequest r){ access.requireManage(hospitalId,branchId,doctorId); if(!doctors.existsByIdAndHospitalIdAndBranchId(doctorId,hospitalId,branchId))throw new NotFoundException("Requested resource was not found"); validate(r); if(schedules.findFirstByDoctorIdAndBranchIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(doctorId,branchId,r.effectiveStartDate()).filter(x->x.getEffectiveFrom().equals(r.effectiveStartDate())).isPresent())throw new ConflictException("Schedule revision already exists"); DoctorScheduleRevision s=new DoctorScheduleRevision(doctorId,branchId,r.effectiveStartDate(),r.slotDurationMinutes()); for(var day:r.days())for(var p:day.workingPeriods()){WorkingPeriod w=new WorkingPeriod(s,day.dayOfWeek().getValue(),p.startTime(),p.endTime()); for(var b:Optional.ofNullable(p.breaks()).orElse(List.of()))w.add(new ScheduleBreak(w,b.startTime(),b.endTime()));s.add(w);} s=schedules.save(s);audit.record("DOCTOR_SCHEDULE_SAVED","DOCTOR_SCHEDULE",s.getId(),hospitalId,"{}");return s; }
 @Transactional(readOnly=true) public DoctorScheduleRevision get(UUID h,UUID b,UUID d,LocalDate date){access.requireRead(h,b,d);return schedules.findFirstByDoctorIdAndBranchIdAndEffectiveFromLessThanEqualOrderByEffectiveFromDesc(d,b,date).orElseThrow(()->new NotFoundException("Requested resource was not found"));}
 private void validate(ScheduleRequest r){for(var d:r.days()){List<ScheduleRequest.Period> ps=d.workingPeriods();for(var p:ps){if(!p.startTime().isBefore(p.endTime()))throw new DomainException("VALIDATION_ERROR","Working period must end after it starts");for(var b:Optional.ofNullable(p.breaks()).orElse(List.of()))if(!b.startTime().isBefore(b.endTime())||b.startTime().isBefore(p.startTime())||b.endTime().isAfter(p.endTime()))throw new DomainException("VALIDATION_ERROR","Invalid break");} for(int i=0;i<ps.size();i++)for(int j=i+1;j<ps.size();j++)if(ps.get(i).startTime().isBefore(ps.get(j).endTime())&&ps.get(j).startTime().isBefore(ps.get(i).endTime()))throw new DomainException("VALIDATION_ERROR","Working periods overlap");}}
}
